{"l":6924,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'forfærdelig' på engelsk i 'The food was ___'?","o":["spicy","fresh","awful","sweet"],"a":"awful","r":"'Awful' = forfærdelig."},
{"l":6938,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'Pupils ___ leave the school during the break without permission.'","o":["don't have to","needn't","aren't allowed","aren't allowed to"],"a":"aren't allowed to","r":"'Aren't allowed to' betyder ikke må. 'Don't have to' betyder ikke behøver."},
{"l":6948,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder 'oversight' i 'The missing name on the list was just an oversight.'?","o":["forglemmelse","oversigt","overraskelse","overdrivelse"],"a":"forglemmelse","r":"'Oversight' betyder en forglemmelse. Falsk ven: en oversigt hedder 'overview'."},
{"l":6949,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'ulækker' på engelsk i 'That smell is ___'?","o":["delicious","disgusting","familiar","surprising"],"a":"disgusting","r":"'Disgusting' = ulækker."},
{"l":6974,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'begejstret' på engelsk i 'She was ___ with the present'?","o":["bored","upset","thrilled","worried"],"a":"thrilled","r":"'Thrilled' = begejstret."},
{"l":6987,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'næsten' på engelsk i 'I ___ missed the bus'?","o":["quickly","finally","suddenly","nearly"],"a":"nearly","r":"'Nearly' = næsten."},
{"l":6999,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'lettet' på engelsk i 'I was ___ when I passed the test'?","o":["relieved","surprised","worried","ashamed"],"a":"relieved","r":"'Relieved' = lettet."},
{"l":7000,"g":7,"b":5,"cefr":"B1","role":"challenge","insight":"reframing","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'mål' på engelsk i 'My ___ is to become a vet'?","o":["problem","goal","hobby","fear"],"a":"goal","r":"'Goal' betyder mål. 'Vet' betyder dyrlæge."},
{"l":7020,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'rare' i 'a rare bird'?","o":["cheap","wild","common","strange"],"a":"common","r":"'Rare' betyder sjælden, og 'common' betyder almindelig."},
{"l":7030,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer: 'The children were ___ by the magician's tricks.'","o":["amazing","amaze","amazement","amazed"],"a":"amazed","r":"Børnene oplever noget, så det er '-ed'-formen: 'amazed'. '-ing'-formen beskriver det, der forbløffer."},
{"l":7050,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer: 'Can you ___ after my cat while I'm on holiday?'","o":["look","see","watch","care"],"a":"look","r":"'Look after' betyder passe på. 'Watch' og 'care' kan ikke bruges med 'after' på den måde."},
{"l":7060,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Maya had promised to help at the cake sale, but she spent the whole afternoon at the cinema. The next day she avoided looking at her friends.' Hvordan har Maya det sandsynligvis?","o":["Hun er stolt af sig selv","Hun har dårlig samvittighed","Hun er vred på sine venner","Hun er træt efter salget"],"a":"Hun har dårlig samvittighed","r":"Maya brød sit løfte og undgår at se på vennerne, hvilket tyder på dårlig samvittighed."},
{"l":7080,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man vil spørge, om pladsen ved siden af er optaget?","o":["Is this place busy?","Are you sitting here free?","Is anyone sitting here?","Is here a free seat?"],"a":"Is anyone sitting here?","r":"'Is anyone sitting here?' er den naturlige måde at spørge på. 'Is here a free seat' har forkert ordstilling."},
{"l":7095,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'Where would you live if you ___ choose any country?'","o":["can","will","may","could"],"a":"could","r":"Betingelse type 2: if-sætningen står i datid, og datid af 'can' er 'could'."},
{"l":7125,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'Do you mind ___ the music down a little?'","o":["turning","to turn","turn","turned"],"a":"turning","r":"Efter 'mind' bruger man -ing-form: 'Do you mind turning ...?'"},
{"l":7140,"g":7,"b":5,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'I wish it ___ so cold today.'","o":["isn't","wasn't","won't be","hasn't been"],"a":"wasn't","r":"Efter 'I wish' om nutiden bruger man datid: 'I wish it wasn't' (eller 'weren't')."},
{"l":7160,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer: 'The teacher asked us to ___ our essays by Friday.'","o":["hand out","hand down","hand in","hand back"],"a":"hand in","r":"'Hand in' betyder aflevere. 'Hand out' betyder dele ud, det gør læreren."},
{"l":7180,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'The bus driver waited for the running boy even though the bus was already late.' Hvad siger det om chaufføren?","o":["Han er utålmodig","Han er ligeglad med tiden","Han er drengens far","Han er hensynsfuld"],"a":"Han er hensynsfuld","r":"Han venter på drengen, selv om bussen er forsinket. Det er hensynsfuldt."},
{"l":7210,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder 'stubborn' i 'My little brother is too stubborn to admit he was wrong'?","o":["stædig","genert","doven","uheldig"],"a":"stædig","r":"'Stubborn' betyder stædig, en der ikke vil give sig."},
{"l":7230,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'If I ___ in your shoes, I would ask for help.'","o":["am","were","be","had"],"a":"were","r":"I betingelse type 2 om noget uvirkeligt bruger man 'were': 'If I were in your shoes'."},
{"l":7245,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man ikke har råd til noget?","o":["I can't effort it.","I don't have the cost.","I can't afford it.","It doesn't pay me."],"a":"I can't afford it.","r":"At have råd til hedder 'afford'. 'Effort' betyder anstrengelse og er en typisk forveksling."},
{"l":7270,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'The new app was supposed to save time. Instead, the teachers now spend their evenings fixing problems with it.' Hvad mener skribenten om appen?","o":["Den har sparet lærerne tid","Den er populær hos eleverne","Den virker kun om aftenen","Den har skabt mere arbejde"],"a":"Den har skabt mere arbejde","r":"'Was supposed to' og 'instead' viser, at appen gjorde det modsatte af det forventede."},
{"l":7300,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man på en restaurant vil foreslå at dele regningen?","o":["Shall we split the bill?","Shall we break the money?","Can we divide the receipt?","Could you lend me the bill?"],"a":"Shall we split the bill?","r":"At dele regningen hedder 'split the bill'. 'Break the money' er en direkte oversættelse, der ikke bruges."},
{"l":7330,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer: 'The company has ___ its prices by ten per cent.'","o":["risen","raised","arisen","rose"],"a":"raised","r":"'Raise' tager et objekt (hæve noget), mens 'rise' ikke gør. Derfor 'has raised its prices'."},
{"l":7360,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'gloomy' i 'a gloomy day'?","o":["grey","windy","bright","foggy"],"a":"bright","r":"'Gloomy' betyder mørk og trist, og 'bright' betyder lys. 'Grey' ligger tæt på 'gloomy'."},
{"l":7375,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'My uncle sold his car and now cycles everywhere, even in winter. He says he has never felt healthier.' Hvordan har ændringen påvirket onklen?","o":["Han savner sin bil","Han er ofte syg","Han cykler kun om sommeren","Han har fået det bedre"],"a":"Han har fået det bedre","r":"Han siger, at han aldrig har haft det sundere. Ændringen har altså været god for ham."},
{"l":7390,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Our neighbour's dog barks every time the postman comes, but it wags its tail at everyone else.' Hvad kan man slutte om hunden?","o":["Den reagerer kun på postbuddet","Den er bange for alle","Den gør hele dagen","Den er meget syg"],"a":"Den reagerer kun på postbuddet","r":"Hunden gør kun af postbuddet og logrer ad alle andre."},
{"l":7415,"g":8,"b":1,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'The receptionist asked whether we ___ a reservation.'","o":["did have","had","have we","had we"],"a":"had","r":"Indirekte ja/nej-spørgsmål: 'whether' + almindelig ordstilling og tiden rykket tilbage."},
{"l":7450,"g":8,"b":2,"cefr":"B2","role":"challenge","insight":"reframing","k":"g","variant":"authored","q":"Hvilket ord passer: 'If the bus had come on time, we ___ the start of the concert.'","o":["didn't miss","won't miss","wouldn't have missed","hadn't missed"],"a":"wouldn't have missed","r":"Betingelse type 3: if + had + kort tillægsform, would have + kort tillægsform om noget, der ikke skete."},
{"l":7470,"g":8,"b":2,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvad betyder 'ashamed' i 'He was ashamed of his behaviour at the party'?","o":["stolt","bange","overrasket","skamfuld"],"a":"skamfuld","r":"'Ashamed of' betyder at skamme sig over noget. 'Stolt' er næsten det modsatte."},
{"l":7480,"g":8,"b":2,"cefr":"B2","role":"challenge","insight":"reframing","k":"l","variant":"authored","q":"Læs: 'Although the instructions said the furniture could be assembled in thirty minutes, it took us the whole evening and two phone calls to a friend.' Hvad mener skribenten om vejledningen?","o":["Den var alt for optimistisk","Den var meget præcis","Den manglede helt","Den var skrevet til en ven"],"a":"Den var alt for optimistisk","r":"Vejledningen lovede 30 minutter, men det tog hele aftenen. Den var altså for optimistisk."},
{"l":7520,"g":8,"b":2,"cefr":"B2","role":"challenge","insight":"reframing","k":"o","variant":"authored","q":"Hvilket ord passer: 'The museum is ___ by bus, but it takes almost an hour.'","o":["acceptable","accessible","accessory","accessibility"],"a":"accessible","r":"'Accessible' betyder til at komme til. 'Acceptable' betyder acceptabel og giver ikke mening her."}
]$$::jsonb) AS e
JOIN (VALUES
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('h', 'hverdagsudtryk', 'comprehension', 'conceptual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
